
--Update RateTab Object Info
IF EXISTS (SELECT * FROM sys.objects WHERE object_id = OBJECT_ID(N'FNtoc_genHtab') AND type IN ( N'FN', N'IF', N'TF', N'FS', N'FT' ) ) 
begin
DROP FUNCTION FNtoc_genHtab
end
GO
CREATE FUNCTION FNtoc_genHtab (@P_TOC AS VARCHAR(10))              
RETURNS Table              
AS RETURN (    

SELECT  TOP 1       
TOC.TOC,      
TOC.FLDID1, TOC.FLDTAG1, GENHTAB_1.FLDCRITERIA AS FLDCRITERIA1, 
TOC.FLDID2, TOC.FLDTAG2, GENHTAB_2.FLDCRITERIA AS FLDCRITERIA2, 
TOC.FLDID3, TOC.FLDTAG3, GENHTAB_3.FLDCRITERIA AS FLDCRITERIA3, 
TOC.FLDID4, TOC.FLDTAG4, GENHTAB_4.FLDCRITERIA AS FLDCRITERIA4, 
TOC.FLDID5, TOC.FLDTAG5, GENHTAB_5.FLDCRITERIA AS FLDCRITERIA5,
TOC.FLDID6, TOC.FLDTAG6, GENHTAB_6.FLDCRITERIA AS FLDCRITERIA6,
TOC.FLDID7, TOC.FLDTAG7, GENHTAB_7.FLDCRITERIA AS FLDCRITERIA7, 
TOC.FLDID8, TOC.FLDTAG8, GENHTAB_8.FLDCRITERIA AS FLDCRITERIA8,
TOC.FLDID9, TOC.FLDTAG9, GENHTAB_9.FLDCRITERIA AS FLDCRITERIA9, 
TOC.FLDID10, TOC.FLDTAG10, GENHTAB_10.FLDCRITERIA AS FLDCRITERIA10,
TOC.FLDID11, TOC.FLDTAG11, GENHTAB_11.FLDCRITERIA AS FLDCRITERIA11, 
TOC.FLDID12, TOC.FLDTAG12, GENHTAB_12.FLDCRITERIA AS FLDCRITERIA12,  
TOC.FLDID13, TOC.FLDTAG13, GENHTAB_13.FLDCRITERIA AS FLDCRITERIA13, 
TOC.FLDID14, TOC.FLDTAG14, GENHTAB_14.FLDCRITERIA AS FLDCRITERIA14, 
TOC.FLDID15, TOC.FLDTAG15, GENHTAB_15.FLDCRITERIA AS FLDCRITERIA15
FROM       
TOC       
LEFT OUTER JOIN GENHTAB as GENHTAB_1 ON TOC.FLDID1<>'' AND TOC.FLDID1 = GENHTAB_1.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_2 ON TOC.FLDID2<>'' AND TOC.FLDID2 = GENHTAB_2.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_3 ON TOC.FLDID3<>'' AND TOC.FLDID3 = GENHTAB_3.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_4 ON TOC.FLDID4<>'' AND TOC.FLDID4 = GENHTAB_4.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_5 ON TOC.FLDID5<>'' AND TOC.FLDID5 = GENHTAB_5.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_6 ON TOC.FLDID6<>'' AND TOC.FLDID6 = GENHTAB_6.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_7 ON TOC.FLDID7<>'' AND TOC.FLDID7 = GENHTAB_7.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_8 ON TOC.FLDID8<>'' AND TOC.FLDID8 = GENHTAB_8.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_9 ON TOC.FLDID9<>'' AND TOC.FLDID9 = GENHTAB_9.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_10 ON TOC.FLDID10<>'' AND TOC.FLDID10 = GENHTAB_10.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_11 ON TOC.FLDID11<>'' AND TOC.FLDID11 = GENHTAB_11.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_12 ON TOC.FLDID12<>'' AND TOC.FLDID12 = GENHTAB_12.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_13 ON TOC.FLDID13<>'' AND TOC.FLDID13 = GENHTAB_13.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_14 ON TOC.FLDID14<>'' AND TOC.FLDID14 = GENHTAB_14.FLDID       
LEFT OUTER JOIN GENHTAB as GENHTAB_15 ON TOC.FLDID15<>'' AND TOC.FLDID15 = GENHTAB_15.FLDID       
WHERE  TOC.TOC lIKE @P_TOC 
)
GO

IF EXISTS ( SELECT * FROM   sysobjects WHERE  id = object_id(N'QRate_Ratcon') and OBJECTPROPERTY(id, N'IsProcedure') = 1 )
begin
DROP PROCEDURE QRate_Ratcon
end
GO
CREATE PROCEDURE QRate_Ratcon (@CODE Varchar(10), @TOC varchar(10) )            
AS            
 BEGIN                    
 SELECT CAST(0 As Bit) ProcessFlag, RATECON, RATECON.CODE AS CODE,MinTSI,MaxTSI,      
RATECON.MINPERIOD, RATECON.MAXPERIOD, RATECON.MINRATE, RATECON.MAXRATE, RATECON.RATE,
 RATETAB.SPERIOD,TEXCESS, RATECON.ALLOWEDF, LOADING,
(Case When FLDCRITERIA1=1 and RATECON.FLDID1<>'' Then F.FLDTAG1+' : '+Case When RATECON.VALUEID1<>'' Then RATECON.VALUEID1+'-'+cast(RATECON.VALUEDESC1 as varchar(100)) ELSE cast(RATECON.VALUEDESC1 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA2=1 and RATECON.FLDID2<>'' Then F.FLDTAG2+' : '+Case When RATECON.VALUEID2<>'' Then RATECON.VALUEID2+'-'+cast(RATECON.VALUEDESC2 as varchar(100)) ELSE cast(RATECON.VALUEDESC2 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA3=1 and RATECON.FLDID3<>'' Then F.FLDTAG3+' : '+Case When RATECON.VALUEID3<>'' Then RATECON.VALUEID3+'-'+cast(RATECON.VALUEDESC3 as varchar(100)) ELSE cast(RATECON.VALUEDESC3 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA4=1 and RATECON.FLDID4<>'' Then F.FLDTAG4+' : '+Case When RATECON.VALUEID4<>'' Then RATECON.VALUEID4+'-'+cast(RATECON.VALUEDESC4 as varchar(100)) ELSE cast(RATECON.VALUEDESC4 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA5=1 and RATECON.FLDID5<>'' Then F.FLDTAG5+' : '+Case When RATECON.VALUEID5<>'' Then RATECON.VALUEID5+'-'+cast(RATECON.VALUEDESC5 as varchar(100)) ELSE cast(RATECON.VALUEDESC5 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA6=1 and RATECON.FLDID6<>'' Then F.FLDTAG6+' : '+Case When RATECON.VALUEID6<>'' Then RATECON.VALUEID6+'-'+cast(RATECON.VALUEDESC6 as varchar(100)) ELSE cast(RATECON.VALUEDESC6 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA7=1 and RATECON.FLDID7<>'' Then F.FLDTAG7+' : '+Case When RATECON.VALUEID7<>'' Then RATECON.VALUEID7+'-'+cast(RATECON.VALUEDESC7 as varchar(100)) ELSE cast(RATECON.VALUEDESC7 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA8=1 and RATECON.FLDID8<>'' Then F.FLDTAG8+' : '+Case When RATECON.VALUEID8<>'' Then RATECON.VALUEID8+'-'+cast(RATECON.VALUEDESC8 as varchar(100)) ELSE cast(RATECON.VALUEDESC8 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA9=1 and RATECON.FLDID9<>'' Then F.FLDTAG9+' : '+Case When RATECON.VALUEID9<>'' Then RATECON.VALUEID9+'-'+cast(RATECON.VALUEDESC9 as varchar(100)) ELSE cast(RATECON.VALUEDESC9 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA10=1 and RATECON.FLDID10<>'' Then F.FLDTAG10+' : '+Case When RATECON.VALUEID10<>'' Then RATECON.VALUEID10+'-'+cast(RATECON.VALUEDESC10 as varchar(100)) ELSE cast(RATECON.VALUEDESC10 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA11=1 and RATECON.FLDID11<>'' Then F.FLDTAG11+' : '+Case When RATECON.VALUEID11<>'' Then RATECON.VALUEID11+'-'+cast(RATECON.VALUEDESC11 as varchar(100)) ELSE cast(RATECON.VALUEDESC11 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA12=1 and RATECON.FLDID12<>'' Then F.FLDTAG12+' : '+Case When RATECON.VALUEID12<>'' Then RATECON.VALUEID12+'-'+cast(RATECON.VALUEDESC12 as varchar(100)) ELSE cast(RATECON.VALUEDESC12 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA13=1 and RATECON.FLDID13<>'' Then F.FLDTAG13+' : '+Case When RATECON.VALUEID13<>'' Then RATECON.VALUEID13+'-'+cast(RATECON.VALUEDESC13 as varchar(100)) ELSE cast(RATECON.VALUEDESC13 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA14=1 and RATECON.FLDID14<>'' Then F.FLDTAG14+' : '+Case When RATECON.VALUEID14<>'' Then RATECON.VALUEID14+'-'+cast(RATECON.VALUEDESC14 as varchar(100)) ELSE cast(RATECON.VALUEDESC14 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA15=1 and RATECON.FLDID15<>'' Then F.FLDTAG15+' : '+Case When RATECON.VALUEID15<>'' Then RATECON.VALUEID15+'-'+cast(RATECON.VALUEDESC15 as varchar(100)) ELSE cast(RATECON.VALUEDESC15 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
 ) AS OBJ_INFO
 from RateCon
  LEFT JOIN RATETAB ON RATETAB.CODE = RATECON.CODE 
  LEFT JOIN FNtoc_genHtab(@TOC) F  ON F.TOC = RATETAB.TOC
   where RATECON.CODE LIKE @CODE   
 end

 go

