 GO
 
CREATE procedure QRate_RATECON_M7 (@CODE Varchar(10), @TOC varchar(10) )      
AS      
 BEGIN      
  SELECT CAST(0 As Bit) ProcessFlag, RATECON_M7.*,
  (Case When FLDCRITERIA1=1 and RATECON_M7.FLDID1<>'' Then F.FLDTAG1+' : '+Case When RATECON_M7.VALUEID1<>'' Then RATECON_M7.VALUEID1+'-'+cast(RATECON_M7.VALUEDESC1 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC1 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA2=1 and RATECON_M7.FLDID2<>'' Then F.FLDTAG2+' : '+Case When RATECON_M7.VALUEID2<>'' Then RATECON_M7.VALUEID2+'-'+cast(RATECON_M7.VALUEDESC2 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC2 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA3=1 and RATECON_M7.FLDID3<>'' Then F.FLDTAG3+' : '+Case When RATECON_M7.VALUEID3<>'' Then RATECON_M7.VALUEID3+'-'+cast(RATECON_M7.VALUEDESC3 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC3 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA4=1 and RATECON_M7.FLDID4<>'' Then F.FLDTAG4+' : '+Case When RATECON_M7.VALUEID4<>'' Then RATECON_M7.VALUEID4+'-'+cast(RATECON_M7.VALUEDESC4 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC4 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA5=1 and RATECON_M7.FLDID5<>'' Then F.FLDTAG5+' : '+Case When RATECON_M7.VALUEID5<>'' Then RATECON_M7.VALUEID5+'-'+cast(RATECON_M7.VALUEDESC5 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC5 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA6=1 and RATECON_M7.FLDID6<>'' Then F.FLDTAG6+' : '+Case When RATECON_M7.VALUEID6<>'' Then RATECON_M7.VALUEID6+'-'+cast(RATECON_M7.VALUEDESC6 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC6 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA7=1 and RATECON_M7.FLDID7<>'' Then F.FLDTAG7+' : '+Case When RATECON_M7.VALUEID7<>'' Then RATECON_M7.VALUEID7+'-'+cast(RATECON_M7.VALUEDESC7 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC7 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA8=1 and RATECON_M7.FLDID8<>'' Then F.FLDTAG8+' : '+Case When RATECON_M7.VALUEID8<>'' Then RATECON_M7.VALUEID8+'-'+cast(RATECON_M7.VALUEDESC8 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC8 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA9=1 and RATECON_M7.FLDID9<>'' Then F.FLDTAG9+' : '+Case When RATECON_M7.VALUEID9<>'' Then RATECON_M7.VALUEID9+'-'+cast(RATECON_M7.VALUEDESC9 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC9 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
+Case When FLDCRITERIA10=1 and RATECON_M7.FLDID10<>'' Then F.FLDTAG10+' : '+Case When RATECON_M7.VALUEID10<>'' Then RATECON_M7.VALUEID10+'-'+cast(RATECON_M7.VALUEDESC10 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC10 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA11=1 and RATECON_M7.FLDID11<>'' Then F.FLDTAG11+' : '+Case When RATECON_M7.VALUEID11<>'' Then RATECON_M7.VALUEID11+'-'+cast(RATECON_M7.VALUEDESC11 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC11 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA12=1 and RATECON_M7.FLDID12<>'' Then F.FLDTAG12+' : '+Case When RATECON_M7.VALUEID12<>'' Then RATECON_M7.VALUEID12+'-'+cast(RATECON_M7.VALUEDESC12 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC12 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA13=1 and RATECON_M7.FLDID13<>'' Then F.FLDTAG13+' : '+Case When RATECON_M7.VALUEID13<>'' Then RATECON_M7.VALUEID13+'-'+cast(RATECON_M7.VALUEDESC13 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC13 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA14=1 and RATECON_M7.FLDID14<>'' Then F.FLDTAG14+' : '+Case When RATECON_M7.VALUEID14<>'' Then RATECON_M7.VALUEID14+'-'+cast(RATECON_M7.VALUEDESC14 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC14 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end

+Case When FLDCRITERIA15=1 and RATECON_M7.FLDID15<>'' Then F.FLDTAG15+' : '+Case When RATECON_M7.VALUEID15<>'' Then RATECON_M7.VALUEID15+'-'+cast(RATECON_M7.VALUEDESC15 as varchar(100)) ELSE cast(RATECON_M7.VALUEDESC15 as varchar(100)) END+'; '+char(13)+char(10) ELSE '' end
 ) AS OBJ_INFO 
  from RATECON_M7
  LEFT JOIN RATETAB ON RATETAB.CODE = RATECON_M7.CODE 
  LEFT JOIN FNtoc_genHtab(@TOC) F  ON F.TOC = RATETAB.TOC
  where RATECON_M7.CODE LIKE @CODE 
 END
 GO
